INSERT INTO webdav_share_entry(job_id,song_id,relative_path,file_size,result_json,filename_json) SELECT @{id},s.id,s.relative_path,s.file_size,COALESCE(f.result_json,r.result_json),s.result_json FROM media_song s JOIN media_source source ON source.id=s.source_id LEFT JOIN webdav_resource r ON r.song_id=s.id LEFT JOIN media_metadata_file f ON f.song_id=s.id AND f.revision=f.synced_revision AND f.source_location=source.location WHERE s.source_id=@{sourceId}
